'use strict';
let cpuSkillReturn=null,cpuSkillSeason=KanjiCpuSkill.seasonId(),cpuSkillClockOffset=0,cpuSkillInfo=KanjiCpuSkill.seasons(),cpuSkillFollowCurrent=true,cpuSkillInfoBusy=null;
const cpuSkillNow=()=>Date.now()+cpuSkillClockOffset;
function initializeCpuSkillDeviceRecords(){if(gameState.cpuSkillDeviceScopeVersion===1)return;if(/^online:.+:[a-f0-9]{32}$/.test(gameState.cpuSkillRecordsOwner||'')){gameState.cpuSkillDeviceScopeVersion=1;return;}gameState.cpuSkillSharedArchive={best:structuredClone(gameState.cpuSkillSeasonBest||{}),scopes:structuredClone(gameState.cpuSkillRecordScopes||{}),owner:gameState.cpuSkillRecordsOwner||null};gameState.cpuSkillSeasonBest={};gameState.cpuSkillRecordScopes={};gameState.cpuSkillRecordsOwner=gameState.playUsageOwner||null;gameState.cpuSkillDeviceScopeVersion=1;for(const e of gameState.playPending||[]){if(!e.cpuSkill||!e.cleared||!KanjiCpuSkill.valid(e))continue;const r={season:e.cpuSkill.season,challenge:e.challenge,score:KanjiCpuSkill.score(e),shots:e.shots,survivors:e.survivors,killTotal:KanjiCpuSkill.killTotal(e),scoringVersion:3};gameState.cpuSkillSeasonBest[r.season]??={};const old=gameState.cpuSkillSeasonBest[r.season][r.challenge];if(!old||KanjiCpuSkill.better(r,old))gameState.cpuSkillSeasonBest[r.season][r.challenge]=r;}}
function cpuSkillBest(id,season=cpuSkillSeason){initializeCpuSkillDeviceRecords();const r=gameState.cpuSkillSeasonBest?.[season]?.[id];if(r){if(r.scoringVersion!==3){r.score=KanjiCpuSkill.recordScore(r);r.killTotal=r.shots*3;r.scoringVersion=3;}return r;}return {score:0,shots:0,survivors:0,killTotal:Infinity};}
function acceptCpuSkillRecords(records){initializeCpuSkillDeviceRecords();for(const raw of records||[]){const r={...raw};if(!KanjiCpuSkill.validSeason(r.season))continue;const season=r.season,c=KanjiCpuSkill.get(r.challenge,season);if(!c||!c.season||!Number.isSafeInteger(r.score)||r.score<0||r.score>1600000)continue;r.killTotal??=r.shots*3;r.scoringVersion=3;if(!KanjiCpuSkill.better(r,cpuSkillBest(r.challenge,season)))continue;gameState.cpuSkillSeasonBest??={};gameState.cpuSkillSeasonBest[season]??={};gameState.cpuSkillSeasonBest[season][r.challenge]={...r};}}
let cpuSkillSaveBusy=null,cpuSkillSaveStatus='';
function bindCpuSkillRecordOwner(owner){initializeCpuSkillDeviceRecords();const previous=gameState.cpuSkillRecordsOwner||gameState.playUsageOwner||null;if(previous&&previous!==owner){gameState.cpuSkillRecordScopes??={};gameState.cpuSkillRecordScopes[previous]=structuredClone(gameState.cpuSkillSeasonBest||{});gameState.cpuSkillSeasonBest=structuredClone(gameState.cpuSkillRecordScopes[owner]||{});}gameState.cpuSkillRecordsOwner=owner;}
window.syncCpuSkillBestRecords=async()=>{if(cpuSkillSaveBusy)return cpuSkillSaveBusy;cpuSkillSaveBusy=(async()=>{try{if(typeof initializeCpuSkillSeasons==='function')await initializeCpuSkillSeasons();const initial=await playerApi('/api/cpu-skill/records');bindCpuSkillRecordOwner(initial.cpuSkillOwner);acceptCpuSkillRecords(initial.cpuSkillRecords);const records=[];for(const [season,items]of Object.entries(gameState.cpuSkillSeasonBest||{})){if(!KanjiCpuSkill.canSubmit(season,cpuSkillNow()))continue;for(const challenge of Object.keys(items)){const r=cpuSkillBest(challenge,season),remote=initial.cpuSkillRecords.find(v=>v.season===season&&v.challenge===challenge);if(r.score>0&&(!remote||KanjiCpuSkill.better(r,remote)))records.push({season,challenge,shots:r.shots,survivors:r.survivors,killTotal:r.killTotal});}}if(records.length){await ensurePlayerProfile();const result=await playerApi('/api/cpu-skill/records','POST',{cpuSkillOwner:initial.cpuSkillOwner,records:records.slice(0,5)});if(result.cpuSkillOwner!==gameState.cpuSkillRecordsOwner)throw Error('ログイン先が変わりました。');acceptCpuSkillRecords(result.cpuSkillRecords);if(result.accepted.length!==Math.min(5,records.length))throw Error('登録期間が終了しました。自己ベストは端末に残っています。');}cpuSkillSaveStatus='ランキングに保存済み';saveState();}catch(error){cpuSkillSaveStatus=error.status===401?'ログインなしでランキングに登録できます。自己ベストは端末に保存しています。':'ランキングへの保存待ち：'+error.message;}finally{const status=prepEl('cpu-skill-save-status');if(status)status.textContent=cpuSkillSaveStatus;cpuSkillSaveBusy=null;}})();return cpuSkillSaveBusy;};
function renderCpuSeasonOptions(){for(const id of ['cpu-skill-season','cpu-skill-dialog-season']){const select=prepEl(id);if(!select)continue;select.replaceChildren();for(const s of cpuSkillInfo.seasons){const o=document.createElement('option');o.value=s.id;o.textContent=s.label+(s.current?'・開催中':'');select.append(o);}select.value=cpuSkillSeason;}}
async function initializeCpuSkillSeasons(){if(cpuSkillInfoBusy)return cpuSkillInfoBusy;cpuSkillInfoBusy=(async()=>{try{const result=await playerApi('/api/cpu-skill/seasons');cpuSkillClockOffset=result.serverNow-Date.now();cpuSkillInfo=result;if(cpuSkillFollowCurrent||!result.seasons.some(s=>s.id===cpuSkillSeason))cpuSkillSeason=result.current;renderCpuSeasonOptions();if(!prepEl('modal-cpu-skill').classList.contains('hidden'))renderCpuSkillChallenges();}catch{cpuSkillInfo=KanjiCpuSkill.seasons(cpuSkillNow());renderCpuSeasonOptions();}finally{cpuSkillInfoBusy=null;}})();return cpuSkillInfoBusy;}
window.selectCpuSkillSeason=season=>{if(!cpuSkillInfo.seasons.some(s=>s.id===season))return;cpuSkillSeason=season;cpuSkillFollowCurrent=season===cpuSkillInfo.current;renderCpuSeasonOptions();renderCpuSkillChallenges();if(prepEl('leaderboard-rule').value==='cpu-skill')loadLeaderboard();};
let cpuSkillOpenRequest=0;
window.openCpuSkillChallenges=async()=>{const request=++cpuSkillOpenRequest;cpuSkillReturn=document.activeElement;if(cpuSkillFollowCurrent){cpuSkillInfo=KanjiCpuSkill.seasons(cpuSkillNow());cpuSkillSeason=cpuSkillInfo.current;}renderCpuSeasonOptions();renderCpuSkillChallenges();pausePlayerOverlay();prepEl('modal-cpu-skill').classList.remove('hidden');prepEl('btn-cpu-skill-close').focus();prepEl('cpu-skill-save-status').textContent='端末の記録を表示中。ランキングの記録を確認しています…';await initializeCpuSkillSeasons();await syncCpuSkillBestRecords();if(request===cpuSkillOpenRequest&&!prepEl('modal-cpu-skill').classList.contains('hidden'))renderCpuSkillChallenges();};
window.closeCpuSkillChallenges=()=>{++cpuSkillOpenRequest;prepEl('modal-cpu-skill').classList.add('hidden');resumePlayerEngine();if(cpuSkillReturn?.isConnected)cpuSkillReturn.focus();};
function renderCpuSkillChallenges(){const list=prepEl('cpu-skill-stage-list'),stages=KanjiCpuSkill.seasonStages(cpuSkillSeason),active=cpuSkillSeason===KanjiCpuSkill.seasonId(cpuSkillNow()),b=KanjiCpuSkill.bounds(cpuSkillSeason);prepEl('cpu-skill-period').textContent=b?`${cpuSkillSeason} シーズン・毎月1日0:00（日本時間）に切替${active?'':'・終了／記録の閲覧のみ'}`:'開催中のシーズンを選んでください。';prepEl('cpu-skill-loan').textContent=`貸出：${(stages[0]?.chars||KanjiCpuSkill.chars).join('・')} ／ 双方Lv.10・ルビなし・配置固定・自分が先攻`;list.replaceChildren();let total=0,clears=0;for(const c of stages){const card=practiceNode('article'),v=cpuSkillBest(c.id),button=practiceNode('button','inventory-action',active?'挑む':'終了');button.dataset.cpuSkill=c.id;button.disabled=!active;button.onclick=()=>startCpuSkillChallenge(c.id);card.append(practiceNode('h3','',c.name.replace('CPU腕試し・','')),practiceNode('p','',`相手：${c.enemies.join('・')}`),practiceNode('p','',v.score?`${KanjiCpuSkill.formatScore(v.score,cpuSkillSeason)}点 ／ ${v.survivors}体生存・${v.shots}回`:'未達成'),button);list.append(card);total+=v.score;clears+=v.score>0?1:0;}prepEl('cpu-skill-total').textContent=`${clears} / ${stages.length}課題達成・合計 ${KanjiCpuSkill.formatScore(total,cpuSkillSeason)}点`;}
window.startCpuSkillChallenge=id=>{const c=KanjiCpuSkill.get(id,cpuSkillSeason);if(!c||!c.season||c.season!==KanjiCpuSkill.seasonId(cpuSkillNow())){showToast('終了したシーズンは記録の閲覧のみです。開催中のシーズンを選んでください。');return;}if(!confirmLeaveEndless())return;setAutoBattle(false);setAutoContinue(false);prepEl('modal-cpu-skill').classList.add('hidden');prepEl('modal-result').classList.add('hidden');specialChallenge=null;endlessRun=null;practiceRun={id,kind:'cpu-skill',challenge:structuredClone(c),team:KanjiCpuSkill.team(KANJI_DATABASE,c),formation:KanjiFormation.copy(c.formation),started:true,finished:false};battleMode='practice';prepEl('modal-battle-menu').classList.add('hidden');switchTab('battle');resetBattle(false,true);};
window.retryCpuSkillChallenge=()=>{if(!isPractice()||practiceRun.kind!=='cpu-skill')return;if(practiceRun.challenge.season!==KanjiCpuSkill.seasonId(cpuSkillNow())){showToast('このシーズンは終了しました。開催中のシーズンを選んでください。');return;}setAutoBattle(false);setAutoContinue(false);if(practiceRun.started&&!practiceRun.finished)recordUsageFinish(false);practiceRun.started=true;practiceRun.finished=false;prepEl('modal-battle-menu').classList.add('hidden');prepEl('modal-result').classList.add('hidden');resetBattle(false,true);};
function finishCpuSkillChallenge(winner){if(isBattleEnded)return;const event=recordUsageFinish(winner);if(!event)return;isBattleEnded=true;practiceRun.finished=true;const season=event.cpuSkill.season,score=KanjiCpuSkill.score(event);if(KanjiCpuSkill.valid(event))acceptCpuSkillRecords([{season,challenge:event.challenge,score,shots:event.shots,survivors:event.survivors,killTotal:KanjiCpuSkill.killTotal(event)}]);saveState(true);syncCpuSkillBestRecords();prepEl('result-title-badge').textContent=event.cleared?'腕試し達成':'腕試し再挑戦';prepEl('result-message').textContent=`${KanjiCpuSkill.formatScore(score,season)}点`;prepEl('result-rp-change').textContent='変動なし';prepEl('result-coin-change').textContent='変動なし';prepEl('result-exp-info').hidden=true;['btn-endless-next','btn-special-next','btn-special-retry','btn-friend-next','btn-friend-result-deck','btn-online-result-next'].forEach(id=>prepEl(id).hidden=true);prepEl('btn-practice-retry').hidden=season!==KanjiCpuSkill.seasonId(cpuSkillNow());prepEl('btn-result-close').textContent='CPU腕試しに戻る';prepEl('modal-result').classList.remove('hidden');playSound(event.cleared?'win':'lose');}
function endCpuSkillChallenge(){const season=practiceRun.challenge.season;cpuSkillSeason=season;cpuSkillFollowCurrent=season===KanjiCpuSkill.seasonId(cpuSkillNow());practiceRun=null;battleMode='classic';prepEl('modal-result').classList.add('hidden');resetBattle();switchTab('rank');setRecordsView('ranking');prepEl('leaderboard-rule').value='cpu-skill';loadLeaderboard();openCpuSkillChallenges();}
const skillDialog=document.createElement('div');skillDialog.id='modal-cpu-skill';skillDialog.className='editor-overlay hidden';skillDialog.setAttribute('role','dialog');skillDialog.setAttribute('aria-modal','true');skillDialog.setAttribute('aria-labelledby','cpu-skill-title');skillDialog.innerHTML='<section class="editor-panel"><div class="editor-title"><h2 id="cpu-skill-title">CPU腕試し</h2><button id="btn-cpu-skill-close" aria-label="CPU腕試しを閉じる" onclick="closeCpuSkillChallenges()">×</button></div><label class="skill-difficulty" for="cpu-skill-dialog-season">シーズン<select id="cpu-skill-dialog-season" onchange="selectCpuSkillSeason(this.value)"></select></label><p id="cpu-skill-period" class="inventory-note"></p><p id="cpu-skill-loan" class="inventory-note"></p><details class="inventory-note"><summary>得点・順位・保存のルール</summary><p>5課題それぞれの自己ベストを端末（ブラウザ）ごとに保存・合計します。復元コードで引き継ぐ場合を除き、別の端末やブラウザの記録とは共有しません。同点なら、相手3体を倒すまでに使った自分の発射回数の合計が少ない方を上位にします。そこまで同じなら同順位。考える時間は採点しません。</p><p>勝利1,000点＋生存1体100点＋発射回数ボーナス（1回で300点、1回増えるごとに−20点、最低0点）。最大1,600点。発射の強さ・終了位置は採点しません。敗北・引き分けは0点。同点でも早く倒すと自己ベストを更新できます。</p><p>育成・段位ポイントは順位に影響せず、経験値・文は変動しません。ログインなしでランキングに登録できます。シーズン終了後15分まで登録可能で、それ以降の結果は端末の記録に残ります。</p></details><p id="cpu-skill-total"></p><p id="cpu-skill-save-status" class="inventory-note" role="status"></p><div id="cpu-skill-stage-list" class="cpu-skill-stages"></div></section>';document.body.append(skillDialog);
document.addEventListener('keydown',e=>{if(skillDialog.classList.contains('hidden'))return;if(e.key==='Escape'){e.preventDefault();closeCpuSkillChallenges();}if(e.key==='Tab'){const nodes=[...skillDialog.querySelectorAll('button:not(:disabled),select,summary')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('load',()=>{initializeCpuSkillDeviceRecords();initializeCpuSkillSeasons();setInterval(()=>{if(cpuSkillInfo.current!==KanjiCpuSkill.seasonId(cpuSkillNow())){initializeCpuSkillSeasons().then(()=>{if(prepEl('leaderboard-rule').value==='cpu-skill')loadLeaderboard();});}},30000);});

window.addEventListener('online',()=>syncCpuSkillBestRecords());
